<script>
(function(){const list=document.getElementById('sections-list'),add=document.getElementById('add-section');if(!list||!add)return;let nextIndex={{ count($initialSections) }};const types=@json($sectionTypes);const assets=@json($assets->map(fn($asset)=>['id'=>$asset->id,'label'=>($asset->title?:$asset->original_name).' · #'.$asset->id])->values());function renumber(){[...list.querySelectorAll('.section-card')].forEach((card,i)=>{card.querySelector('strong').textContent='Bölüm '+(i+1);card.querySelectorAll('[name]').forEach(el=>{el.name=el.name.replace(/sections\[\d+\]/,'sections['+i+']')})})}function bind(card){card.querySelector('.remove-section').addEventListener('click',()=>{card.remove();renumber()});card.querySelector('.move-up').addEventListener('click',()=>{if(card.previousElementSibling)list.insertBefore(card,card.previousElementSibling);renumber()});card.querySelector('.move-down').addEventListener('click',()=>{if(card.nextElementSibling)list.insertBefore(card.nextElementSibling,card);renumber()})}function field(label,name,tag='input',attrs=''){return '<div class="field"><label>'+label+'</label><'+tag+' name="sections['+nextIndex+']['+name+']" '+attrs+'></'+tag+'></div>'}add.addEventListener('click',()=>{const card=document.createElement('article');card.className='module section-card';card.style.marginTop='14px';let options=Object.entries(types).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');let assetOptions='<option value="">Görsel seçilmedi</option>'+assets.map(a=>'<option value="'+a.id+'">'+a.label.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</option>').join('');card.innerHTML='<div class="quick-actions"><strong>Bölüm</strong><div><button type="button" class="btn secondary move-up">↑</button> <button type="button" class="btn secondary move-down">↓</button> <button type="button" class="btn secondary remove-section">Kaldır</button></div></div><div class="field"><label>Bölüm türü</label><select name="sections['+nextIndex+'][type]">'+options+'</select></div>'+field('Başlık','title','input','maxlength="180"')+field('Alt başlık','subtitle','input','maxlength="240"')+field('Metin','body','textarea','rows="4" maxlength="12000"')+'<div class="field"><label>Görsel</label><select name="sections['+nextIndex+'][image_asset_id]">'+assetOptions+'</select></div>'+field('Görsel alternatif metni','image_alt','input','maxlength="250"')+field('Buton metni','cta_label','input','maxlength="80"')+field('Buton adresi','cta_url','input','maxlength="500" placeholder="/demo veya https://..."')+'<div class="field"><label>Görünüm</label><select name="sections['+nextIndex+'][variant]"><option value="default">Standart</option><option value="soft">Yumuşak</option><option value="dark">Koyu</option><option value="accent">Vurgu</option></select></div>'+field('Kart/SSS/adım öğeleri (Slider: Başlık | Açıklama | Görsel ID | Buton | URL)','items_text','textarea','rows="3" maxlength="12000"')+'<input type="hidden" name="sections['+nextIndex+'][is_active]" value="0"><label><input type="checkbox" name="sections['+nextIndex+'][is_active]" value="1" checked> Bu bölüm aktif</label>';list.appendChild(card);nextIndex++;bind(card);renumber()});list.querySelectorAll('.section-card').forEach(bind)})();
</script>
@endsection
